"""Repeat-traffic scenario: one paraphrase per test question, generated by a small model.

The original questions warm the cache; the paraphrases are the test set. This simulates the same
question asked again in different words, which WixQA's disjoint splits never contain.
"""

from __future__ import annotations

import json
import tempfile
from collections.abc import Callable, Sequence
from pathlib import Path

from ragtrail.eval.claude import Invoke, json_block, parse_output, run_claude, text_command
from ragtrail.eval.data import EvalQuestion

SYSTEM = "You rewrite customer support questions. Reply with JSON only."

PROMPT = """\
Rewrite each question below the way a different customer might ask the same thing: same intent and same
specifics (product names, settings, numbers), but in your own words. Vary the wording naturally; do not just
reorder the original. Do not answer the questions.

Reply with a JSON array of objects {{"id": ..., "question": ...}}, one per input, same ids.

{items}"""


def paraphrase_prompt(questions: Sequence[EvalQuestion]) -> str:
    """The prompt for one batch.

    >>> q = EvalQuestion(id="q1", split="s", question="How do I add a domain?", answer="")
    >>> '"id": "q1"' in paraphrase_prompt([q])
    True
    """
    items = json.dumps(
        [{"id": q.id, "question": q.question} for q in questions], ensure_ascii=False, indent=1
    )
    return PROMPT.format(items=items)


def apply_paraphrases(questions: Sequence[EvalQuestion], output: str) -> list[EvalQuestion]:
    """Turn model output into paraphrased questions (`id` + `-p`, gold and answer kept).

    Items with unknown ids, empty text or a copy of the original are dropped.

    >>> q = EvalQuestion(id="q1", split="s", question="How do I add a domain?", answer="A", gold=["n2"])
    >>> [p.question for p in apply_paraphrases([q], '[{"id": "q1", "question": "Adding a domain: how?"}]')]
    ['Adding a domain: how?']
    """
    by_id = {q.id: q for q in questions}
    out = []
    for item in json_block(output):
        original = by_id.get(str(item.get("id")))
        text = str(item.get("question") or "").strip()
        if original is None or not text or text.lower() == original.question.strip().lower():
            continue
        out.append(
            original.model_copy(
                update={
                    "id": f"{original.id}-p",
                    "split": "paraphrase",
                    "question": text,
                    "source_id": original.id,
                }
            )
        )
    return out


def paraphrase_all(
    questions: Sequence[EvalQuestion],
    *,
    model: str = "haiku",
    batch_size: int = 25,
    invoke: Invoke = run_claude,
    echo: Callable[[str], None] = print,
) -> list[EvalQuestion]:
    """Paraphrase every question in batches through `claude -p`."""
    out: list[EvalQuestion] = []
    with tempfile.TemporaryDirectory(prefix="ragtrail-para-") as tmp:
        for start in range(0, len(questions), batch_size):
            batch = questions[start : start + batch_size]
            result = parse_output(
                invoke(text_command(paraphrase_prompt(batch), model=model, system=SYSTEM), Path(tmp))
            )
            done = apply_paraphrases(batch, str(result.get("result") or ""))
            out.extend(done)
            echo(f"paraphrased {len(done)}/{len(batch)} (batch {start // batch_size + 1})")
    return out
